-- ===== 20261015010000_message_edit_delete.sql =====
-- Edit / delete your own messages. Both are soft: the row stays so the chat can
-- show "edited" / "message deleted", but a delete scrubs the text.
alter table public.messages
  add column if not exists edited_at timestamptz,
  add column if not exists deleted_at timestamptz;

-- Only the sender can change their message, only while the chat is open
-- (accepted), and only the text/markers - never read_at or the sender.
create or replace function public.edit_message(p_message_id uuid, p_body text)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_body is null or length(btrim(p_body)) = 0 then
    raise exception 'Message cannot be empty';
  end if;

  update public.messages m
     set body = btrim(p_body),
         edited_at = now()
   where m.id = p_message_id
     and m.sender_id = auth.uid()
     and m.deleted_at is null
     and exists (
       select 1 from public.interests i
        where i.id = m.interest_id and i.status = 'accepted'
     );

  if not found then
    raise exception 'Message can no longer be edited';
  end if;
end;
$$;

create or replace function public.delete_message(p_message_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.messages m
     set body = 'This message was deleted',
         deleted_at = now()
   where m.id = p_message_id
     and m.sender_id = auth.uid()
     and m.deleted_at is null
     and exists (
       select 1 from public.interests i
        where i.id = m.interest_id and i.status = 'accepted'
     );

  if not found then
    raise exception 'Message can no longer be deleted';
  end if;
end;
$$;

revoke all on function public.edit_message(uuid, text) from public;
revoke all on function public.delete_message(uuid) from public;
grant execute on function public.edit_message(uuid, text) to authenticated;
grant execute on function public.delete_message(uuid) to authenticated;

-- ===== 20261015020000_delete_account.sql =====
-- In-app account deletion. Called by the signed-in user; removes everything they
-- own, then the auth user itself. Runs as the function owner (postgres) because
-- regular users cannot delete from auth.users.
--
-- If you have other tables that reference the user, add them here (or give their
-- foreign keys ON DELETE CASCADE) before the final delete from auth.users.
create or replace function public.delete_my_account()
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  uid uuid := auth.uid();
begin
  if uid is null then
    raise exception 'Not signed in';
  end if;

  -- Chats: everything they sent, and every conversation they were part of.
  delete from public.messages
   where sender_id = uid
      or interest_id in (
        select id from public.interests where from_user = uid or to_user = uid
      );

  delete from public.interests where from_user = uid or to_user = uid;
  delete from public.positions where recruiter_id = uid;
  delete from public.profiles where id = uid;

  delete from auth.users where id = uid;
end;
$$;

revoke all on function public.delete_my_account() from public, anon;
grant execute on function public.delete_my_account() to authenticated;

-- ===== 20261017000000_response_timers.sql =====
-- Anti-ghosting response timers.
--
-- Each posting gets an urgency level; the app turns it into a reply window
-- (urgent = 2 hours, standard = 24 hours, flexible = 3 days) and shows a timer on
-- anything waiting for a reply. Nothing is closed or blocked; timers only alert.
alter table public.positions
  add column if not exists urgency text not null default 'standard';

-- (Safe to run again: any earlier copy of these checks is replaced.)
alter table public.positions
  drop constraint if exists positions_urgency_valid;

alter table public.positions
  add constraint positions_urgency_valid
    check (urgency in ('urgent', 'standard', 'flexible'));

-- Interest timers start when the interest was sent. This is a no-op if the column
-- already exists; on a fresh column, existing rows start their clock at migration time.
alter table public.interests
  add column if not exists created_at timestamptz not null default now();

-- ===== 20261017010000_server_time.sql =====
-- Lets the app measure how far a phone's clock is from the server's, so reply timers
-- (whose deadlines are server timestamps) are right even when a phone's clock is off.
-- Harmless if missing: the app just falls back to the phone's own clock.
create or replace function public.server_time()
returns timestamptz
language sql
stable
as $$
  select now();
$$;

revoke all on function public.server_time() from public, anon;
grant execute on function public.server_time() to authenticated;

-- ===== 20261017020000_decline_reasons.sql =====
-- Declining an interest now comes with a reason, so people aren't left guessing why.
alter table public.interests
  add column if not exists decline_reason text,
  add column if not exists decline_note text,
  add column if not exists declined_at timestamptz;

-- (Safe to run again: any earlier copy of these checks is replaced.)
alter table public.interests
  drop constraint if exists interests_decline_reason_valid,
  drop constraint if exists interests_decline_note_length;

alter table public.interests
  add constraint interests_decline_reason_valid
    check (decline_reason is null or decline_reason in (
      'position_filled',
      'missing_certification',
      'not_enough_experience',
      'schedule_mismatch',
      'too_far',
      'chose_another',
      'pay_mismatch',
      'wrong_work',
      'took_another_job',
      'other'
    )),
  add constraint interests_decline_note_length
    check (decline_note is null or char_length(decline_note) <= 280);

-- The only way to decline: records the reason and rejects the interest in one step.
-- Only the person the interest was sent to can call it, and only while it's still
-- pending. (Anyone else, or an already-answered interest, gets an error.)
create or replace function public.decline_interest(
  p_interest_id uuid,
  p_reason text,
  p_note text default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_reason is null then
    raise exception 'Please choose a reason';
  end if;

  update public.interests
     set status = 'rejected',
         decline_reason = p_reason,
         decline_note = nullif(btrim(coalesce(p_note, '')), ''),
         declined_at = now()
   where id = p_interest_id
     and to_user = auth.uid()
     and status = 'pending';

  if not found then
    raise exception 'This interest was already answered';
  end if;
end;
$$;

revoke all on function public.decline_interest(uuid, text, text) from public, anon;
grant execute on function public.decline_interest(uuid, text, text) to authenticated;

-- ===== 20261017030000_remove_declined_interests.sql =====
-- Lets the person who sent an interest remove it from their list once it's been declined.
--
-- This hides the interest rather than deleting it: Discover skips anyone you've already
-- sent an interest to, so deleting the row would put someone who just declined you back
-- in your deck.
alter table public.interests
  add column if not exists sender_hidden boolean not null default false;

-- Only the sender can hide it, and only after it has been declined.
create or replace function public.hide_declined_interest(p_interest_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.interests
     set sender_hidden = true
   where id = p_interest_id
     and from_user = auth.uid()
     and status = 'rejected';

  if not found then
    raise exception 'Only a declined interest you sent can be removed';
  end if;
end;
$$;

revoke all on function public.hide_declined_interest(uuid) from public, anon;
grant execute on function public.hide_declined_interest(uuid) to authenticated;

-- ===== 20261018000000_close_chat_reasons.sql =====
-- Closing a chat now comes with a reason (a positive "deal closed" or a way of not
-- moving forward), and closed chats are archived rather than just marked closed.
alter table public.interests
  add column if not exists closed_reason text,
  add column if not exists closed_note text,
  add column if not exists closed_at timestamptz,
  add column if not exists closed_by uuid references auth.users(id) on delete set null;

-- (Safe to run again: any earlier copy of these checks is replaced.)
alter table public.interests
  drop constraint if exists interests_closed_reason_valid,
  drop constraint if exists interests_closed_note_length;

alter table public.interests
  add constraint interests_closed_reason_valid
    check (closed_reason is null or closed_reason in (
      'deal_closed',
      'not_interested',
      'no_response',
      'position_filled',
      'missing_certification',
      'not_enough_experience',
      'schedule_mismatch',
      'too_far',
      'chose_another',
      'pay_mismatch',
      'wrong_work',
      'took_another_job',
      'other'
    )),
  add constraint interests_closed_note_length
    check (closed_note is null or char_length(closed_note) <= 280);

-- The only way to close a chat: records the reason and archives it in one step.
-- Either person in the chat can call it, and only while it's still active.
create or replace function public.close_chat(
  p_interest_id uuid,
  p_reason text,
  p_note text default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_reason is null then
    raise exception 'Please choose a reason';
  end if;

  update public.interests
     set status = 'closed',
         closed_reason = p_reason,
         closed_note = nullif(btrim(coalesce(p_note, '')), ''),
         closed_at = now(),
         closed_by = auth.uid()
   where id = p_interest_id
     and status = 'accepted'
     and (from_user = auth.uid() or to_user = auth.uid());

  if not found then
    raise exception 'This chat was already closed';
  end if;
end;
$$;

revoke all on function public.close_chat(uuid, text, text) from public, anon;
grant execute on function public.close_chat(uuid, text, text) to authenticated;

-- Archived chats are read-only: nothing can be sent into a chat that isn't active.
create or replace function public.block_messages_in_closed_chats()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if not exists (
    select 1 from public.interests
     where id = new.interest_id and status = 'accepted'
  ) then
    raise exception 'This chat is closed';
  end if;
  return new;
end;
$$;

drop trigger if exists messages_only_in_active_chats on public.messages;
create trigger messages_only_in_active_chats
  before insert on public.messages
  for each row execute function public.block_messages_in_closed_chats();

-- ===== 20261018010000_hide_archived_chats.sql =====
-- Deleting an archived chat removes it from your own list only. The row is kept (the
-- other person still has their archive, and Discover keeps excluding them).
alter table public.interests
  add column if not exists from_chat_hidden boolean not null default false,
  add column if not exists to_chat_hidden boolean not null default false;

create or replace function public.hide_archived_chat(p_interest_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.interests
     set from_chat_hidden = from_chat_hidden or from_user = auth.uid(),
         to_chat_hidden = to_chat_hidden or to_user = auth.uid()
   where id = p_interest_id
     and status = 'closed'
     and (from_user = auth.uid() or to_user = auth.uid());

  if not found then
    raise exception 'Only archived chats can be deleted';
  end if;
end;
$$;

revoke all on function public.hide_archived_chat(uuid) from public, anon;
grant execute on function public.hide_archived_chat(uuid) to authenticated;

-- ===== 20261018020000_response_ratings.sql =====
-- Response rating: everyone starts at 5.0 stars. Answering on time keeps it up (and
-- brings it back after a miss); missing a reply deadline pulls it down.
--
-- A "response" is either answering an interest someone sent you or replying to a chat
-- message. The deadline comes from the posting's urgency (urgent 2h, standard 24h,
-- flexible 72h) and matches lib/response-timers.ts. Only the last 30 responses count,
-- so a rough patch fades as you keep replying on time.
--
--   rating = 5 * (on_time + 3) / (total + 3)
--
-- The 3 is a head start of three on-time replies, so one slip early on isn't brutal.

-- When did the person answer an interest? (Accepting had no timestamp before.)
alter table public.interests
  add column if not exists responded_at timestamptz;

create or replace function public.stamp_interest_response()
returns trigger
language plpgsql
as $$
begin
  if old.status = 'pending' and new.status <> 'pending' and new.responded_at is null then
    new.responded_at := now();
  end if;
  return new;
end;
$$;

drop trigger if exists interests_stamp_response on public.interests;
create trigger interests_stamp_response
  before update on public.interests
  for each row execute function public.stamp_interest_response();

create or replace function public.response_window(p_urgency text)
returns interval
language sql
immutable
as $$
  select case p_urgency
    when 'urgent' then interval '2 hours'
    when 'flexible' then interval '72 hours'
    else interval '24 hours'
  end;
$$;

-- Ratings for several people at once (used for Discover cards and profiles).
create or replace function public.get_ratings(p_user_ids uuid[])
returns table (user_id uuid, rating numeric, on_time int, late int)
language sql
stable
security definer
set search_path = public
as $$
  with users as (
    select distinct unnest(p_user_ids) as uid
  ),
  -- Interests someone sent to this person: answered, or still unanswered past the deadline.
  interest_events as (
    select u.uid,
           i.created_at + public.response_window(p.urgency) as due,
           coalesce(i.responded_at, i.declined_at) as responded
      from users u
      join public.interests i on i.to_user = u.uid
      left join public.positions p on p.id = i.position_id
     where i.status = 'pending'
        or coalesce(i.responded_at, i.declined_at) is not null
  ),
  -- Chat messages that started a run from the other person, and this person's first reply.
  chat_events as (
    select u.uid,
           s.created_at + public.response_window(p.urgency) as due,
           (select min(r.created_at)
              from public.messages r
             where r.interest_id = s.interest_id
               and r.sender_id = u.uid
               and r.created_at > s.created_at) as responded,
           i.status
      from users u
      join public.interests i on (i.from_user = u.uid or i.to_user = u.uid)
      left join public.positions p on p.id = i.position_id
      join lateral (
        select m.*, lag(m.sender_id) over (order by m.created_at) as prev_sender
          from public.messages m
         where m.interest_id = i.id
      ) s on true
     where s.sender_id <> u.uid
       and s.prev_sender is distinct from s.sender_id
       and s.deleted_at is null
  ),
  events as (
    select uid, due, responded from interest_events
    union all
    select uid, due, responded from chat_events
     where responded is not null or (status = 'accepted' and due < now())
  ),
  ranked as (
    select uid,
           (responded is not null and responded <= due) as ok,
           row_number() over (partition by uid order by due desc) as rn
      from events
     where responded is not null or due < now()
  ),
  counts as (
    select uid,
           count(*) filter (where ok)::int as ok_count,
           count(*) filter (where not ok)::int as late_count
      from ranked
     where rn <= 30
     group by uid
  )
  select u.uid,
         round(5.0 * (coalesce(c.ok_count, 0) + 3)
               / (coalesce(c.ok_count, 0) + coalesce(c.late_count, 0) + 3), 1),
         coalesce(c.ok_count, 0),
         coalesce(c.late_count, 0)
    from users u
    left join counts c on c.uid = u.uid;
$$;

revoke all on function public.get_ratings(uuid[]) from public, anon;
grant execute on function public.get_ratings(uuid[]) to authenticated;

-- ===== 20261019000000_position_close_dates.sql =====
-- Positions can have a hire-by / close date.
--
-- When it passes, the position closes automatically: it leaves Discover, interests that
-- were still waiting on it are returned to the people who sent them (and they're told),
-- and chats that already started stay open. Before it closes, the recruiter is reminded
-- to extend the date or confirm it.
alter table public.positions
  add column if not exists close_at timestamptz,
  add column if not exists closed_at timestamptz,
  add column if not exists close_confirmed_at timestamptz;

-- A third way an interest can end: its position closed before anyone answered.
alter table public.interests drop constraint if exists interests_status_check;
-- (Safe to run again: any earlier copy of these checks is replaced.)
alter table public.interests
  drop constraint if exists interests_status_check;

alter table public.interests
  add constraint interests_status_check
    check (status in ('pending', 'accepted', 'rejected', 'closed', 'position_closed'));

-- The closing isn't something the recruiter "answered", so it isn't stamped as a reply.
create or replace function public.stamp_interest_response()
returns trigger
language plpgsql
as $$
begin
  if old.status = 'pending' and new.status not in ('pending', 'position_closed')
     and new.responded_at is null then
    new.responded_at := now();
  end if;
  return new;
end;
$$;

-- Senders can also clear an interest whose position closed.
create or replace function public.hide_declined_interest(p_interest_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.interests
     set sender_hidden = true
   where id = p_interest_id
     and from_user = auth.uid()
     and status in ('rejected', 'position_closed');

  if not found then
    raise exception 'Only a declined or closed interest you sent can be removed';
  end if;
end;
$$;

-- Closes every position whose date has passed. Safe to call any time and as often as you
-- like (the app calls it as it refreshes; the schedule at the bottom does too when
-- pg_cron is available). Returns how many positions it closed.
create or replace function public.close_expired_positions()
returns int
language plpgsql
security definer
set search_path = public
as $$
declare
  closed int;
begin
  with expired as (
    update public.positions
       set active = false,
           closed_at = now()
     where active
       and close_at is not null
       and close_at <= now()
    returning id
  ),
  returned as (
    update public.interests i
       set status = 'position_closed'
      from expired e
     where i.position_id = e.id
       and i.status = 'pending'
    returning i.id
  )
  select count(*) into closed from expired;

  return closed;
end;
$$;

revoke all on function public.close_expired_positions() from public, anon;
grant execute on function public.close_expired_positions() to authenticated;

-- Move the date (and reopen the position if it had already closed).
create or replace function public.extend_position(p_position_id uuid, p_close_at timestamptz)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_close_at is null or p_close_at <= now() then
    raise exception 'Choose a date in the future';
  end if;

  update public.positions
     set close_at = p_close_at,
         close_confirmed_at = null,
         closed_at = null,
         active = true
   where id = p_position_id
     and recruiter_id = auth.uid();

  if not found then
    raise exception 'Position not found';
  end if;
end;
$$;

-- "Yes, it should close on this date": stops the reminders.
create or replace function public.confirm_position_close(p_position_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.positions
     set close_confirmed_at = now()
   where id = p_position_id
     and recruiter_id = auth.uid()
     and active
     and close_at is not null;

  if not found then
    raise exception 'Position not found';
  end if;
end;
$$;

revoke all on function public.extend_position(uuid, timestamptz) from public, anon;
grant execute on function public.extend_position(uuid, timestamptz) to authenticated;
revoke all on function public.confirm_position_close(uuid) from public, anon;
grant execute on function public.confirm_position_close(uuid) to authenticated;

-- Same as before, except interests that were left unanswered until their position closed
-- only count against you when the deadline had already passed by then.
create or replace function public.get_ratings(p_user_ids uuid[])
returns table (user_id uuid, rating numeric, on_time int, late int)
language sql
stable
security definer
set search_path = public
as $$
  with users as (
    select distinct unnest(p_user_ids) as uid
  ),
  -- Interests someone sent to this person: answered, or still unanswered past the deadline.
  interest_events as (
    select u.uid,
           i.created_at + public.response_window(p.urgency) as due,
           coalesce(i.responded_at, i.declined_at) as responded,
           i.status,
           p.closed_at as position_closed_at
      from users u
      join public.interests i on i.to_user = u.uid
      left join public.positions p on p.id = i.position_id
     where i.status = 'pending'
        or coalesce(i.responded_at, i.declined_at) is not null
        -- Unanswered when the position closed: only a miss if the deadline came first.
        or (i.status = 'position_closed'
            and i.created_at + public.response_window(p.urgency) < p.closed_at)
  ),
  -- Chat messages that started a run from the other person, and this person's first reply.
  chat_events as (
    select u.uid,
           s.created_at + public.response_window(p.urgency) as due,
           (select min(r.created_at)
              from public.messages r
             where r.interest_id = s.interest_id
               and r.sender_id = u.uid
               and r.created_at > s.created_at) as responded,
           i.status
      from users u
      join public.interests i on (i.from_user = u.uid or i.to_user = u.uid)
      left join public.positions p on p.id = i.position_id
      join lateral (
        select m.*, lag(m.sender_id) over (order by m.created_at) as prev_sender
          from public.messages m
         where m.interest_id = i.id
      ) s on true
     where s.sender_id <> u.uid
       and s.prev_sender is distinct from s.sender_id
       and s.deleted_at is null
  ),
  events as (
    select uid, due, responded from interest_events
     -- A position-closed interest is never answered; it's only here if it was already late.
     where status <> 'position_closed' or responded is null
    union all
    select uid, due, responded from chat_events
     where responded is not null or (status = 'accepted' and due < now())
  ),
  ranked as (
    select uid,
           (responded is not null and responded <= due) as ok,
           row_number() over (partition by uid order by due desc) as rn
      from events
     where responded is not null or due < now()
  ),
  counts as (
    select uid,
           count(*) filter (where ok)::int as ok_count,
           count(*) filter (where not ok)::int as late_count
      from ranked
     where rn <= 30
     group by uid
  )
  select u.uid,
         round(5.0 * (coalesce(c.ok_count, 0) + 3)
               / (coalesce(c.ok_count, 0) + coalesce(c.late_count, 0) + 3), 1),
         coalesce(c.ok_count, 0),
         coalesce(c.late_count, 0)
    from users u
    left join counts c on c.uid = u.uid;
$$;

revoke all on function public.get_ratings(uuid[]) from public, anon;
grant execute on function public.get_ratings(uuid[]) to authenticated;

-- Run the closer every minute where pg_cron is installed, so positions close on time even
-- when nobody has the app open. (Without it, they close the next time anyone refreshes.)
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('close-expired-positions', '* * * * *',
                          'select public.close_expired_positions()');
  end if;
end;
$$;

-- ===== 20261019010000_close_position_now.sql =====
-- Close a position by hand, any time. It behaves just like an automatic close: the
-- position leaves Discover, interests still waiting on it are returned to the people who
-- sent them, and chats that already started stay open.
create or replace function public.close_position(p_position_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.positions
     set active = false,
         closed_at = now()
   where id = p_position_id
     and recruiter_id = auth.uid()
     and active;

  if not found then
    raise exception 'This position is already closed';
  end if;

  update public.interests
     set status = 'position_closed'
   where position_id = p_position_id
     and status = 'pending';
end;
$$;

-- Reopen a position without picking a new date. A close date that has already passed is
-- cleared (it would just close the position again); a future one is kept.
create or replace function public.reopen_position(p_position_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.positions
     set active = true,
         closed_at = null,
         close_confirmed_at = null,
         close_at = case when close_at is not null and close_at <= now() then null else close_at end
   where id = p_position_id
     and recruiter_id = auth.uid()
     and not active;

  if not found then
    raise exception 'This position is already open';
  end if;
end;
$$;

revoke all on function public.close_position(uuid) from public, anon;
grant execute on function public.close_position(uuid) to authenticated;
revoke all on function public.reopen_position(uuid) from public, anon;
grant execute on function public.reopen_position(uuid) to authenticated;

-- ===== 20261019020000_reopen_clears_returned_interests.sql =====
-- When a closed position opens again, the interests that were returned to people when it
-- closed are cleared, so those people can show interest in it again. (Without this, the
-- old returned row would block a new interest in the same position.)
create or replace function public.extend_position(p_position_id uuid, p_close_at timestamptz)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_close_at is null or p_close_at <= now() then
    raise exception 'Choose a date in the future';
  end if;

  update public.positions
     set close_at = p_close_at,
         close_confirmed_at = null,
         closed_at = null,
         active = true
   where id = p_position_id
     and recruiter_id = auth.uid();

  if not found then
    raise exception 'Position not found';
  end if;

  delete from public.interests
   where position_id = p_position_id
     and status = 'position_closed';
end;
$$;

create or replace function public.reopen_position(p_position_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.positions
     set active = true,
         closed_at = null,
         close_confirmed_at = null,
         close_at = case when close_at is not null and close_at <= now() then null else close_at end
   where id = p_position_id
     and recruiter_id = auth.uid()
     and not active;

  if not found then
    raise exception 'This position is already open';
  end if;

  delete from public.interests
   where position_id = p_position_id
     and status = 'position_closed';
end;
$$;

-- ===== 20261020000000_location_coordinates.sql =====
-- Locations can now be picked on a map. The place name stays in `location`; the pin's
-- coordinates (rounded to roughly 100 m) are stored next to it for distance features.
alter table public.profiles
  add column if not exists location_lat double precision,
  add column if not exists location_lng double precision;

alter table public.positions
  add column if not exists location_lat double precision,
  add column if not exists location_lng double precision;

-- (Safe to run again: any earlier copy of these checks is replaced.)
alter table public.profiles
  drop constraint if exists profiles_location_coords_valid;

alter table public.profiles
  add constraint profiles_location_coords_valid
    check ((location_lat is null) = (location_lng is null)
           and (location_lat is null or (location_lat between -90 and 90 and location_lng between -180 and 180)));

-- (Safe to run again: any earlier copy of these checks is replaced.)
alter table public.positions
  drop constraint if exists positions_location_coords_valid;

alter table public.positions
  add constraint positions_location_coords_valid
    check ((location_lat is null) = (location_lng is null)
           and (location_lat is null or (location_lat between -90 and 90 and location_lng between -180 and 180)));

-- ===== 20261020010000_resumes_storage.sql =====
-- Resumes live in a private "resumes" bucket. The app opens them with short-lived signed
-- links, so only the owner and recruiters can read one; the old public links stop working.
insert into storage.buckets (id, name, public)
values ('resumes', 'resumes', false)
on conflict (id) do update set public = false;

-- You manage files in your own folder ("<your user id>/resume.pdf").
drop policy if exists "resumes: owner can write" on storage.objects;
create policy "resumes: owner can write"
  on storage.objects for all to authenticated
  using (bucket_id = 'resumes' and (storage.foldername(name))[1] = auth.uid()::text)
  with check (bucket_id = 'resumes' and (storage.foldername(name))[1] = auth.uid()::text);

-- Recruiters can read any resume (so they can view candidates').
drop policy if exists "resumes: recruiters can read" on storage.objects;
create policy "resumes: recruiters can read"
  on storage.objects for select to authenticated
  using (
    bucket_id = 'resumes'
    and exists (
      select 1 from public.profiles p where p.id = auth.uid() and p.is_recruiter
    )
  );

-- ===== 20261021000000_archived_chat_messages_readable.sql =====
-- Archived chats keep their history. Messages used to be readable only while the chat was
-- active; this also lets the two people in a chat read its messages after it's closed.
-- (Sending stays blocked: the messages_only_in_active_chats trigger rejects new messages.)
drop policy if exists "messages: participants can read archived chats" on public.messages;
create policy "messages: participants can read archived chats"
  on public.messages for select to authenticated
  using (
    exists (
      select 1 from public.interests i
       where i.id = messages.interest_id
         and i.status in ('accepted', 'closed')
         and (i.from_user = auth.uid() or i.to_user = auth.uid())
    )
  );

-- ===== 20261022000000_first_message_timer.sql =====
-- Matches now have a clock from the start: the recruiter is expected to send the first
-- message within the posting's reply window (the same one used for every other reply). This
-- counts toward their response rating like any other reply.
create or replace function public.get_ratings(p_user_ids uuid[])
returns table (user_id uuid, rating numeric, on_time int, late int)
language sql
stable
security definer
set search_path = public
as $$
  with users as (
    select distinct unnest(p_user_ids) as uid
  ),
  -- Interests someone sent to this person: answered, or still unanswered past the deadline.
  interest_events as (
    select u.uid,
           i.created_at + public.response_window(p.urgency) as due,
           coalesce(i.responded_at, i.declined_at) as responded,
           i.status,
           p.closed_at as position_closed_at
      from users u
      join public.interests i on i.to_user = u.uid
      left join public.positions p on p.id = i.position_id
     where i.status = 'pending'
        or coalesce(i.responded_at, i.declined_at) is not null
        -- Unanswered when the position closed: only a miss if the deadline came first.
        or (i.status = 'position_closed'
            and i.created_at + public.response_window(p.urgency) < p.closed_at)
  ),
  -- Chat messages that started a run from the other person, and this person's first reply.
  chat_events as (
    select u.uid,
           s.created_at + public.response_window(p.urgency) as due,
           (select min(r.created_at)
              from public.messages r
             where r.interest_id = s.interest_id
               and r.sender_id = u.uid
               and r.created_at > s.created_at) as responded,
           i.status
      from users u
      join public.interests i on (i.from_user = u.uid or i.to_user = u.uid)
      left join public.positions p on p.id = i.position_id
      join lateral (
        select m.*, lag(m.sender_id) over (order by m.created_at) as prev_sender
          from public.messages m
         where m.interest_id = i.id
      ) s on true
     where s.sender_id <> u.uid
       and s.prev_sender is distinct from s.sender_id
       and s.deleted_at is null
  ),
  -- Recruiters should open the conversation: once a match is made, the first message is
  -- theirs to send, within the posting's reply window. (Matches made before response times
  -- were recorded have no start time and are skipped.)
  first_move_events as (
    select u.uid,
           i.responded_at + public.response_window(p.urgency) as due,
           (select min(m.created_at) from public.messages m where m.interest_id = i.id) as responded,
           i.status
      from users u
      join public.profiles pr on pr.id = u.uid and pr.is_recruiter
      join public.interests i on (i.from_user = u.uid or i.to_user = u.uid)
                              and i.responded_at is not null
                              and i.status in ('accepted', 'closed')
      left join public.positions p on p.id = i.position_id
  ),
  events as (
    select uid, due, responded from interest_events
     -- A position-closed interest is never answered; it's only here if it was already late.
     where status <> 'position_closed' or responded is null
    union all
    select uid, due, responded from chat_events
     where responded is not null or (status = 'accepted' and due < now())
    union all
    select uid, due, responded from first_move_events
     where responded is not null or (status = 'accepted' and due < now())
  ),
  ranked as (
    select uid,
           (responded is not null and responded <= due) as ok,
           row_number() over (partition by uid order by due desc) as rn
      from events
     where responded is not null or due < now()
  ),
  counts as (
    select uid,
           count(*) filter (where ok)::int as ok_count,
           count(*) filter (where not ok)::int as late_count
      from ranked
     where rn <= 30
     group by uid
  )
  select u.uid,
         round(5.0 * (coalesce(c.ok_count, 0) + 3)
               / (coalesce(c.ok_count, 0) + coalesce(c.late_count, 0) + 3), 1),
         coalesce(c.ok_count, 0),
         coalesce(c.late_count, 0)
    from users u
    left join counts c on c.uid = u.uid;
$$;


revoke all on function public.get_ratings(uuid[]) from public, anon;
grant execute on function public.get_ratings(uuid[]) to authenticated;

-- ===== 20261023000000_phone_verified.sql =====
-- Phone verification: the app texts a code to confirm someone has a real phone number.
-- Other people only ever see *that* the number is verified (a badge), never the number.
alter table public.profiles
  add column if not exists phone_verified_at timestamptz;

-- Nobody can set their own verified flag. Only the sync below (which flags itself) can.
create or replace function public.protect_phone_verified()
returns trigger
language plpgsql
as $$
begin
  if coalesce(current_setting('app.phone_sync', true), '') <> 'on' then
    if tg_op = 'INSERT' then
      new.phone_verified_at := null;
    else
      new.phone_verified_at := old.phone_verified_at;
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists profiles_protect_phone_verified on public.profiles;
create trigger profiles_protect_phone_verified
  before insert or update on public.profiles
  for each row execute function public.protect_phone_verified();

-- When Supabase confirms a phone number, copy that onto the profile.
create or replace function public.sync_phone_verified()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform set_config('app.phone_sync', 'on', true);
  update public.profiles set phone_verified_at = new.phone_confirmed_at where id = new.id;
  perform set_config('app.phone_sync', 'off', true);
  return new;
end;
$$;

drop trigger if exists on_auth_user_phone_confirmed on auth.users;
create trigger on_auth_user_phone_confirmed
  after update of phone_confirmed_at on auth.users
  for each row
  when (new.phone_confirmed_at is distinct from old.phone_confirmed_at)
  execute function public.sync_phone_verified();

-- Anyone who already confirmed a number gets the badge.
do $$
begin
  perform set_config('app.phone_sync', 'on', true);
  update public.profiles p
     set phone_verified_at = u.phone_confirmed_at
    from auth.users u
   where u.id = p.id and u.phone_confirmed_at is not null;
end;
$$;

-- ===== 20261024000000_verification_requests.sql =====
-- Document verification. People request a check (an EPA 608 card, a contractor license, a
-- certificate of insurance); reviewers approve or reject it in the app; approved checks show
-- as badges. Evidence photos live in a private bucket and are deleted after the decision.

-- Reviewers are people who may decide requests. Set it yourself in the SQL editor:
--   update public.profiles set is_reviewer = true where username = 'someone';
alter table public.profiles add column if not exists is_reviewer boolean not null default false;

-- The app can never grant reviewer access: only the SQL editor / service role can.
create or replace function public.protect_reviewer_flag()
returns trigger
language plpgsql
as $$
begin
  if current_user in ('authenticated', 'anon') then
    if tg_op = 'INSERT' then
      new.is_reviewer := false;
    else
      new.is_reviewer := old.is_reviewer;
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists profiles_protect_reviewer on public.profiles;
create trigger profiles_protect_reviewer
  before insert or update on public.profiles
  for each row execute function public.protect_reviewer_flag();

create table if not exists public.verification_requests (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  kind text not null check (kind in ('epa_608', 'contractor_license', 'insurance')),
  license_number text check (license_number is null or char_length(license_number) <= 40),
  license_state text check (license_state is null or license_state ~ '^[A-Z]{2}$'),
  evidence_paths text[] not null default '{}',
  note text check (note is null or char_length(note) <= 500),
  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  reviewer_id uuid references auth.users(id) on delete set null,
  reviewed_at timestamptz,
  reject_reason text check (reject_reason is null or char_length(reject_reason) <= 400),
  created_at timestamptz not null default now()
);

-- One request waiting per person and kind.
create unique index if not exists verification_one_pending
  on public.verification_requests (user_id, kind) where status = 'pending';

alter table public.verification_requests enable row level security;
drop policy if exists "verification: read own requests" on public.verification_requests;
create policy "verification: read own requests"
  on public.verification_requests for select to authenticated
  using (user_id = auth.uid());
-- (No insert/update policies: everything goes through the functions below.)

-- What's been approved. Anyone signed in can read it (it only says "has this badge").
create table if not exists public.user_verifications (
  user_id uuid not null references auth.users(id) on delete cascade,
  kind text not null check (kind in ('epa_608', 'contractor_license', 'insurance')),
  detail text,
  verified_at timestamptz not null default now(),
  expires_at timestamptz,
  request_id uuid references public.verification_requests(id) on delete set null,
  primary key (user_id, kind)
);

alter table public.user_verifications enable row level security;
drop policy if exists "verification: badges are public" on public.user_verifications;
create policy "verification: badges are public"
  on public.user_verifications for select to authenticated
  using (true);

create or replace function public.is_reviewer()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce((select is_reviewer from public.profiles where id = auth.uid()), false);
$$;

-- Ask for a check.
create or replace function public.submit_verification(
  p_kind text,
  p_license_number text default null,
  p_license_state text default null,
  p_paths text[] default '{}',
  p_note text default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  recruiter boolean;
  new_id uuid;
  path text;
begin
  select is_recruiter into recruiter from public.profiles where id = auth.uid();
  if recruiter is null then
    raise exception 'Finish setting up your profile first';
  end if;

  if p_kind = 'epa_608' and recruiter then
    raise exception 'EPA 608 verification is for job seekers';
  elsif p_kind in ('contractor_license', 'insurance') and not recruiter then
    raise exception 'That verification is for recruiters';
  elsif p_kind not in ('epa_608', 'contractor_license', 'insurance') then
    raise exception 'Unknown verification type';
  end if;

  if array_length(p_paths, 1) > 4 then
    raise exception 'Attach at most 4 files';
  end if;
  foreach path in array coalesce(p_paths, '{}') loop
    if path not like auth.uid()::text || '/%' then
      raise exception 'Invalid file';
    end if;
  end loop;

  if p_kind in ('epa_608', 'insurance') and coalesce(array_length(p_paths, 1), 0) = 0 then
    raise exception 'Attach a photo or PDF';
  end if;
  if p_kind = 'contractor_license' and (
       coalesce(btrim(p_license_number), '') = '' or p_license_state is null) then
    raise exception 'Enter your license number and state';
  end if;

  if exists (
    select 1 from public.user_verifications v
     where v.user_id = auth.uid() and v.kind = p_kind
       and (v.expires_at is null or v.expires_at > now())
  ) then
    raise exception 'You are already verified for this';
  end if;

  begin
    insert into public.verification_requests
      (user_id, kind, license_number, license_state, evidence_paths, note)
    values
      (auth.uid(), p_kind, nullif(btrim(coalesce(p_license_number, '')), ''),
       upper(btrim(p_license_state)), coalesce(p_paths, '{}'), nullif(btrim(coalesce(p_note, '')), ''))
    returning id into new_id;
  exception when unique_violation then
    raise exception 'You already have a request waiting for review';
  end;

  return new_id;
end;
$$;

-- Reviewers: everything waiting, oldest first.
create or replace function public.list_pending_verifications()
returns table (
  id uuid,
  user_id uuid,
  kind text,
  license_number text,
  license_state text,
  evidence_paths text[],
  note text,
  created_at timestamptz,
  name text,
  username text,
  is_recruiter boolean,
  company_name text,
  location text,
  epa_608_types text[],
  trade_start_year int
)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not public.is_reviewer() then
    raise exception 'Not allowed';
  end if;

  return query
    select r.id, r.user_id, r.kind, r.license_number, r.license_state, r.evidence_paths,
           r.note, r.created_at, p.name, p.username, p.is_recruiter, p.company_name,
           p.location, p.epa_608_types, p.trade_start_year
      from public.verification_requests r
      join public.profiles p on p.id = r.user_id
     where r.status = 'pending'
     order by r.created_at asc;
end;
$$;

-- Reviewers: approve or reject one request. You can't decide your own.
create or replace function public.review_verification(
  p_request_id uuid,
  p_approve boolean,
  p_reason text default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  req public.verification_requests%rowtype;
begin
  if not public.is_reviewer() then
    raise exception 'Not allowed';
  end if;

  select * into req from public.verification_requests where id = p_request_id for update;
  if not found or req.status <> 'pending' then
    raise exception 'This request was already decided';
  end if;
  if req.user_id = auth.uid() then
    raise exception 'You can''t review your own request';
  end if;
  if not p_approve and coalesce(btrim(p_reason), '') = '' then
    raise exception 'Give a reason so they can fix it';
  end if;

  update public.verification_requests
     set status = case when p_approve then 'approved' else 'rejected' end,
         reviewer_id = auth.uid(),
         reviewed_at = now(),
         reject_reason = case when p_approve then null else left(btrim(p_reason), 400) end
   where id = req.id;

  if p_approve then
    insert into public.user_verifications (user_id, kind, detail, verified_at, expires_at, request_id)
    values (
      req.user_id, req.kind,
      case when req.kind = 'contractor_license' then req.license_state end,
      now(),
      -- Licenses and insurance lapse; an EPA 608 certification doesn't.
      case when req.kind = 'epa_608' then null else now() + interval '1 year' end,
      req.id
    )
    on conflict (user_id, kind) do update
      set detail = excluded.detail, verified_at = excluded.verified_at,
          expires_at = excluded.expires_at, request_id = excluded.request_id;
  end if;
end;
$$;

-- Badges for several people at once (current ones only).
create or replace function public.get_verifications(p_user_ids uuid[])
returns table (user_id uuid, kind text, detail text)
language sql
stable
security definer
set search_path = public
as $$
  select v.user_id, v.kind, v.detail
    from public.user_verifications v
   where v.user_id = any (p_user_ids)
     and (v.expires_at is null or v.expires_at > now());
$$;

revoke all on function public.is_reviewer() from public, anon;
revoke all on function public.submit_verification(text, text, text, text[], text) from public, anon;
revoke all on function public.list_pending_verifications() from public, anon;
revoke all on function public.review_verification(uuid, boolean, text) from public, anon;
revoke all on function public.get_verifications(uuid[]) from public, anon;
grant execute on function public.is_reviewer() to authenticated;
grant execute on function public.submit_verification(text, text, text, text[], text) to authenticated;
grant execute on function public.list_pending_verifications() to authenticated;
grant execute on function public.review_verification(uuid, boolean, text) to authenticated;
grant execute on function public.get_verifications(uuid[]) to authenticated;

-- Evidence goes in a private bucket: you can add files to your own folder, reviewers can read
-- and delete any (they delete it once a request is decided).
insert into storage.buckets (id, name, public)
values ('verification-docs', 'verification-docs', false)
on conflict (id) do update set public = false;

drop policy if exists "verification-docs: owner can upload" on storage.objects;
create policy "verification-docs: owner can upload"
  on storage.objects for insert to authenticated
  with check (bucket_id = 'verification-docs' and (storage.foldername(name))[1] = auth.uid()::text);

drop policy if exists "verification-docs: reviewers can read" on storage.objects;
create policy "verification-docs: reviewers can read"
  on storage.objects for select to authenticated
  using (bucket_id = 'verification-docs' and public.is_reviewer());

drop policy if exists "verification-docs: reviewers can delete" on storage.objects;
