-- ===== 20261025000000_conversation_summaries.sql =====
-- One row per chat with what the Messages list needs: the last message, how many are unread,
-- and when the unanswered run from the other person started. Computed in the database so it
-- stays correct however many messages there are (the app used to read only the newest 500
-- across all chats, so a very busy chat could make quieter ones look empty).
create or replace function public.conversation_summaries()
returns table (
  interest_id uuid,
  last_text text,
  last_at timestamptz,
  last_from_me boolean,
  last_read boolean,
  unread int,
  awaiting_since timestamptz
)
language sql
stable
security definer
set search_path = public
as $$
  with mine as (
    select i.id as interest_id
      from public.interests i
     where i.status in ('accepted', 'closed')
       and auth.uid() in (i.from_user, i.to_user)
  ),
  last_message as (
    select distinct on (m.interest_id)
           m.interest_id,
           case when m.deleted_at is not null then 'Message deleted' else m.body end as last_text,
           m.created_at as last_at,
           (m.sender_id = auth.uid()) as last_from_me,
           (m.read_at is not null) as last_read
      from public.messages m
      join mine on mine.interest_id = m.interest_id
     order by m.interest_id, m.created_at desc
  ),
  my_last as (
    select m.interest_id, max(m.created_at) as at
      from public.messages m
      join mine on mine.interest_id = m.interest_id
     where m.sender_id = auth.uid()
     group by m.interest_id
  ),
  theirs as (
    select m.interest_id,
           count(*) filter (where m.read_at is null and m.deleted_at is null)::int as unread,
           -- The oldest live message from them since my last reply (null if answered).
           min(m.created_at) filter (
             where m.deleted_at is null and m.created_at > coalesce(ml.at, '-infinity')
           ) as awaiting_since
      from public.messages m
      join mine on mine.interest_id = m.interest_id
      left join my_last ml on ml.interest_id = m.interest_id
     where m.sender_id <> auth.uid()
     group by m.interest_id
  )
  select l.interest_id, l.last_text, l.last_at, l.last_from_me, l.last_read,
         coalesce(t.unread, 0), t.awaiting_since
    from last_message l
    left join theirs t on t.interest_id = l.interest_id;
$$;

revoke all on function public.conversation_summaries() from public, anon;
grant execute on function public.conversation_summaries() to authenticated;

-- ===== 20261025010000_interest_guards.sql =====
-- Server-side rules the app already enforces on screen, so they hold even if a screen is stale
-- (or someone talks to the API directly):
--   * you can't send an interest tied to a position that's closed
--   * you can have at most 10 interests waiting at once (MAX_INTERESTS in the app)
create or replace function public.check_new_interest()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.position_id is not null and exists (
    select 1 from public.positions p
     where p.id = new.position_id
       and (not p.active or (p.close_at is not null and p.close_at <= now()))
  ) then
    raise exception 'This position is closed';
  end if;

  if (select count(*) from public.interests i
       where i.from_user = new.from_user and i.status = 'pending') >= 10 then
    raise exception 'You have reached your limit of 10 interests. Wait for replies or take one back.';
  end if;

  return new;
end;
$$;

drop trigger if exists interests_check_new on public.interests;
create trigger interests_check_new
  before insert on public.interests
  for each row execute function public.check_new_interest();

-- ===== 20261025020000_verification_docs_owner_cleanup.sql =====
-- You can see and delete your own pending verification files (needed to clean them up when
-- you delete your account). Reviewers keep their existing read/delete access.
drop policy if exists "verification-docs: owner can read own" on storage.objects;
create policy "verification-docs: owner can read own"
  on storage.objects for select to authenticated
  using (bucket_id = 'verification-docs' and (storage.foldername(name))[1] = auth.uid()::text);

drop policy if exists "verification-docs: owner can delete own" on storage.objects;
create policy "verification-docs: owner can delete own"
  on storage.objects for delete to authenticated
  using (bucket_id = 'verification-docs' and (storage.foldername(name))[1] = auth.uid()::text);

-- ===== 20261026000000_hardening.sql =====
-- Hardening, from a review of the earlier migrations.
--
--  * People can't flip their own role (it gates resume access and which verifications they
--    can ask for) or write the columns that feed ratings and chat state on interests; only
--    accepting an interest addressed to you is allowed directly, everything else goes through
--    the functions.
--  * Overdue interests are remembered when a position closes, so reopening the position
--    can't erase the misses from a recruiter's rating.
--  * The first-message check only counts the recruiter's own message, and the rating no
--    longer disagrees with the reply timers about deleted messages.
--  * The 10-interest limit holds when several are sent at once.
--  * A position's close date can't be pushed more than a year out.

-- Role can't be changed after signup by the app (the SQL editor and functions still can).
create or replace function public.protect_is_recruiter()
returns trigger
language plpgsql
as $$
begin
  if current_user in ('authenticated', 'anon') then
    new.is_recruiter := old.is_recruiter;
  end if;
  return new;
end;
$$;

drop trigger if exists profiles_protect_role on public.profiles;
create trigger profiles_protect_role
  before update on public.profiles
  for each row execute function public.protect_is_recruiter();

-- From the app, an interest can only be changed by its recipient accepting it. Named so it
-- runs before the trigger that stamps responded_at.
create or replace function public.guard_interest_update()
returns trigger
language plpgsql
as $$
begin
  if current_user in ('authenticated', 'anon') then
    new.responded_at := old.responded_at;
    new.declined_at := old.declined_at;
    new.decline_reason := old.decline_reason;
    new.decline_note := old.decline_note;
    new.closed_reason := old.closed_reason;
    new.closed_note := old.closed_note;
    new.closed_at := old.closed_at;
    new.closed_by := old.closed_by;
    new.sender_hidden := old.sender_hidden;
    new.from_chat_hidden := old.from_chat_hidden;
    new.to_chat_hidden := old.to_chat_hidden;
    new.from_user := old.from_user;
    new.to_user := old.to_user;
    new.position_id := old.position_id;
    new.created_at := old.created_at;

    if not (old.status = 'pending' and new.status = 'accepted' and old.to_user = auth.uid()) then
      new.status := old.status;
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists interests_a_guard on public.interests;
create trigger interests_a_guard
  before update on public.interests
  for each row execute function public.guard_interest_update();

-- Replies that were already overdue when their position closed.
create table if not exists public.missed_replies (
  interest_id uuid primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  due timestamptz not null
);
alter table public.missed_replies enable row level security;
-- (No policies: only the functions below read or write it.)

-- Anything already returned before this migration counts the same way.
insert into public.missed_replies (interest_id, user_id, due)
select i.id, i.to_user, i.created_at + public.response_window(p.urgency)
  from public.interests i
  join public.positions p on p.id = i.position_id
 where i.status = 'position_closed'
   and p.closed_at is not null
   and i.created_at + public.response_window(p.urgency) < p.closed_at
on conflict do nothing;

create or replace function public.close_expired_positions()
returns int
language plpgsql
security definer
set search_path = public
as $$
declare
  closed int;
begin
  with expired as (
    update public.positions
       set active = false,
           closed_at = now()
     where active
       and close_at is not null
       and close_at <= now()
    returning id, urgency
  ),
  late as (
    insert into public.missed_replies (interest_id, user_id, due)
    select i.id, i.to_user, i.created_at + public.response_window(e.urgency)
      from public.interests i
      join expired e on e.id = i.position_id
     where i.status = 'pending'
       and i.created_at + public.response_window(e.urgency) < now()
    on conflict do nothing
    returning 1
  ),
  returned as (
    update public.interests i
       set status = 'position_closed'
      from expired e
     where i.position_id = e.id
       and i.status = 'pending'
    returning i.id
  )
  select count(*) into closed from expired;

  return closed;
end;
$$;

create or replace function public.close_position(p_position_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  urg text;
begin
  update public.positions
     set active = false,
         closed_at = now()
   where id = p_position_id
     and recruiter_id = auth.uid()
     and active
  returning urgency into urg;

  if not found then
    raise exception 'This position is already closed';
  end if;

  insert into public.missed_replies (interest_id, user_id, due)
  select i.id, i.to_user, i.created_at + public.response_window(urg)
    from public.interests i
   where i.position_id = p_position_id
     and i.status = 'pending'
     and i.created_at + public.response_window(urg) < now()
  on conflict do nothing;

  update public.interests
     set status = 'position_closed'
   where position_id = p_position_id
     and status = 'pending';
end;
$$;

create or replace function public.extend_position(p_position_id uuid, p_close_at timestamptz)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_close_at is null or p_close_at <= now() then
    raise exception 'Choose a date in the future';
  end if;
  if p_close_at > now() + interval '366 days' then
    raise exception 'Choose a date within the next year';
  end if;

  update public.positions
     set close_at = p_close_at,
         close_confirmed_at = null,
         closed_at = null,
         active = true
   where id = p_position_id
     and recruiter_id = auth.uid();

  if not found then
    raise exception 'Position not found';
  end if;

  delete from public.interests
   where position_id = p_position_id
     and status = 'position_closed';
end;
$$;

-- Same limits as before, but safe when several interests arrive at once.
create or replace function public.check_new_interest()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.position_id is not null and exists (
    select 1 from public.positions p
     where p.id = new.position_id
       and (not p.active or (p.close_at is not null and p.close_at <= now()))
  ) then
    raise exception 'This position is closed';
  end if;

  -- One sender at a time, so two simultaneous inserts can't both slip under the limit.
  perform pg_advisory_xact_lock(hashtext('interest-limit:' || new.from_user::text));

  if (select count(*) from public.interests i
       where i.from_user = new.from_user and i.status = 'pending') >= 10 then
    raise exception 'You have reached your limit of 10 interests. Wait for replies or take one back.';
  end if;

  return new;
end;
$$;

create or replace function public.get_ratings(p_user_ids uuid[])
returns table (user_id uuid, rating numeric, on_time int, late int)
language sql
stable
security definer
set search_path = public
as $$
  with users as (
    select distinct unnest(p_user_ids) as uid
  ),
  -- Interests someone sent to this person: answered, or still unanswered past the deadline.
  interest_events as (
    select u.uid,
           i.created_at + public.response_window(p.urgency) as due,
           coalesce(i.responded_at, i.declined_at) as responded
      from users u
      join public.interests i on i.to_user = u.uid
      left join public.positions p on p.id = i.position_id
     where i.status = 'pending'
        or coalesce(i.responded_at, i.declined_at) is not null
  ),
  -- Interests that were already overdue when their position closed. Recorded at that moment
  -- (see close_position), so reopening the position can't wipe the miss.
  missed as (
    select r.user_id as uid, r.due, null::timestamptz as responded
      from users u
      join public.missed_replies r on r.user_id = u.uid
  ),
  -- Chat messages that started a run from the other person, and this person's first reply.
  chat_events as (
    select u.uid,
           s.created_at + public.response_window(p.urgency) as due,
           (select min(r.created_at)
              from public.messages r
             where r.interest_id = s.interest_id
               and r.sender_id = u.uid
               and r.created_at > s.created_at) as responded,
           i.status
      from users u
      join public.interests i on (i.from_user = u.uid or i.to_user = u.uid)
      left join public.positions p on p.id = i.position_id
      join lateral (
        select m.*, lag(m.sender_id) over (order by m.created_at) as prev_sender
          from public.messages m
         -- A deleted message from them is no longer something to answer; one of mine still
         -- counted as an answer. This matches how the app's reply timers read a chat.
         where m.interest_id = i.id
           and (m.deleted_at is null or m.sender_id = u.uid)
      ) s on true
     where s.sender_id <> u.uid
       and s.prev_sender is distinct from s.sender_id
       and s.deleted_at is null
  ),
  -- Recruiters should open the conversation: once a match is made, the first message is
  -- theirs to send, within the posting's reply window. (Matches made before response times
  -- were recorded have no start time and are skipped.)
  first_move_events as (
    select u.uid,
           i.responded_at + public.response_window(p.urgency) as due,
           (select min(m.created_at)
              from public.messages m
             where m.interest_id = i.id and m.sender_id = u.uid) as responded,
           i.status
      from users u
      join public.profiles pr on pr.id = u.uid and pr.is_recruiter
      join public.interests i on (i.from_user = u.uid or i.to_user = u.uid)
                              and i.responded_at is not null
                              and i.status in ('accepted', 'closed')
      left join public.positions p on p.id = i.position_id
     -- If the other person wrote first, within the window, their message is what's owed a
     -- reply (that's counted under chat_events), not a missed first move.
     where not exists (
       select 1 from public.messages m2
        where m2.interest_id = i.id
          and m2.sender_id <> u.uid
          and m2.deleted_at is null
          and m2.created_at <= i.responded_at + public.response_window(p.urgency)
     )
  ),
  events as (
    select uid, due, responded from interest_events
    union all
    select uid, due, responded from missed
    union all
    select uid, due, responded from chat_events
     where responded is not null or (status = 'accepted' and due < now())
    union all
    select uid, due, responded from first_move_events
     where responded is not null or (status = 'accepted' and due < now())
  ),
  ranked as (
    select uid,
           (responded is not null and responded <= due) as ok,
           row_number() over (partition by uid order by due desc) as rn
      from events
     where responded is not null or due < now()
  ),
  counts as (
    select uid,
           count(*) filter (where ok)::int as ok_count,
           count(*) filter (where not ok)::int as late_count
      from ranked
     where rn <= 30
     group by uid
  )
  select u.uid,
         round(5.0 * (coalesce(c.ok_count, 0) + 3)
               / (coalesce(c.ok_count, 0) + coalesce(c.late_count, 0) + 3), 1),
         coalesce(c.ok_count, 0),
         coalesce(c.late_count, 0)
    from users u
    left join counts c on c.uid = u.uid;
$$;


revoke all on function public.get_ratings(uuid[]) from public, anon;
grant execute on function public.get_ratings(uuid[]) to authenticated;

-- ===== 20261027000000_only_finished_profiles.sql =====
-- Someone who signs up but leaves before finishing setup has a profile with no name. Those
-- shouldn't be shown to anyone, and no interest should be sent to or from one. (Discover
-- now skips them too; this keeps it true even from a stale screen.)
create or replace function public.check_new_interest()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if exists (
    select 1 from public.profiles p
     where p.id in (new.from_user, new.to_user)
       and not coalesce(p.onboarded, false)
  ) then
    raise exception 'That profile isn''t set up yet';
  end if;

  if new.position_id is not null and exists (
    select 1 from public.positions p
     where p.id = new.position_id
       and (not p.active or (p.close_at is not null and p.close_at <= now()))
  ) then
    raise exception 'This position is closed';
  end if;

  -- One sender at a time, so two simultaneous inserts can't both slip under the limit.
  perform pg_advisory_xact_lock(hashtext('interest-limit:' || new.from_user::text));

  if (select count(*) from public.interests i
       where i.from_user = new.from_user and i.status = 'pending') >= 10 then
    raise exception 'You have reached your limit of 10 interests. Wait for replies or take one back.';
  end if;

  return new;
end;
$$;

-- ===== 20261028000000_reply_windows.sql =====
-- Agreed reply times.
--
-- Everyone sets how quickly they usually reply (1 to 5 whole days) in their profile. When two people
-- match, the chat's reply window is the midpoint of their two settings, rounded up to a whole day.
-- Urgent postings start at their 2-hour promise instead. Either person can later ask to change it
-- (urgent postings get shorter options too), and it only changes if the other person accepts. A
-- change applies to messages sent after it, never backwards. Chats made before this keep using the
-- posting's urgency window.

alter table public.profiles
  add column if not exists reply_days int not null default 2
    check (reply_days between 1 and 5);

-- The window in force for a chat, from a moment on. A chat with no entries (made before agreed
-- windows existed) falls back to the posting's urgency window.
create table if not exists public.reply_window_changes (
  interest_id uuid not null,
  effective_from timestamptz not null,
  hours int not null check (hours between 1 and 120),
  primary key (interest_id, effective_from)
);
alter table public.reply_window_changes enable row level security;
-- (No policies: read through chat_reply_windows(), written by the functions below.)

create table if not exists public.reply_window_requests (
  id uuid primary key default gen_random_uuid(),
  interest_id uuid not null,
  requested_by uuid not null references auth.users(id) on delete cascade,
  hours int not null check (hours between 1 and 120),
  status text not null default 'pending' check (status in ('pending', 'accepted', 'declined', 'expired')),
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default now() + interval '3 days',
  decided_at timestamptz
);
alter table public.reply_window_requests enable row level security;

-- One open request per chat.
create unique index if not exists reply_window_one_pending
  on public.reply_window_requests (interest_id) where status = 'pending';

-- The reply window for a chat at a given moment.
create or replace function public.chat_window(p_interest uuid, p_at timestamptz, p_urgency text)
returns interval
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    (select make_interval(hours => c.hours)
       from public.reply_window_changes c
      where c.interest_id = p_interest and c.effective_from <= p_at
      order by c.effective_from desc
      limit 1),
    public.response_window(p_urgency)
  );
$$;

-- Where a new match starts: urgent postings keep their 2-hour promise; everything else is the
-- midpoint of the two people's settings, rounded up to a whole day.
create or replace function public.starting_reply_hours(p_interest public.interests)
returns int
language sql
stable
security definer
set search_path = public
as $$
  select case
    when (select pos.urgency from public.positions pos where pos.id = p_interest.position_id) = 'urgent'
      then 2
    else 24 * ceil((
      coalesce((select reply_days from public.profiles where id = p_interest.from_user), 2)
      + coalesce((select reply_days from public.profiles where id = p_interest.to_user), 2)
    ) / 2.0)::int
  end;
$$;

-- Record the starting window the moment an interest is accepted.
create or replace function public.record_starting_window()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if old.status = 'pending' and new.status = 'accepted' then
    insert into public.reply_window_changes (interest_id, effective_from, hours)
    values (new.id, now(), public.starting_reply_hours(new))
    on conflict do nothing;
  end if;
  return new;
end;
$$;

drop trigger if exists interests_record_window on public.interests;
create trigger interests_record_window
  after update on public.interests
  for each row execute function public.record_starting_window();

-- The windows for my chats (every change, oldest first).
create or replace function public.chat_reply_windows()
returns table (interest_id uuid, effective_from timestamptz, hours int)
language sql
stable
security definer
set search_path = public
as $$
  select c.interest_id, c.effective_from, c.hours
    from public.reply_window_changes c
    join public.interests i on i.id = c.interest_id
   where auth.uid() in (i.from_user, i.to_user)
   order by c.interest_id, c.effective_from;
$$;

-- Ask to change a chat's reply window.
create or replace function public.request_reply_window(p_interest_id uuid, p_hours int)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  i public.interests%rowtype;
  urg text;
  urgent boolean;
  current_hours int;
  new_id uuid;
begin
  select * into i from public.interests where id = p_interest_id;
  if not found or i.status <> 'accepted' or auth.uid() not in (i.from_user, i.to_user) then
    raise exception 'This chat is not active';
  end if;

  select pos.urgency into urg
    from public.interests x left join public.positions pos on pos.id = x.position_id
   where x.id = i.id;
  urgent := coalesce(urg = 'urgent', false);

  -- Whole days from 1 to 5; urgent postings also get shorter options.
  if not (p_hours in (24, 48, 72, 96, 120) or (urgent and p_hours in (2, 4, 12))) then
    raise exception 'That reply time is not available';
  end if;

  select extract(epoch from public.chat_window(i.id, now(), urg)) / 3600 into current_hours;
  if current_hours = p_hours then
    raise exception 'That is already the reply time';
  end if;

  update public.reply_window_requests
     set status = 'expired', decided_at = now()
   where interest_id = i.id and status = 'pending' and expires_at <= now();

  begin
    insert into public.reply_window_requests (interest_id, requested_by, hours)
    values (i.id, auth.uid(), p_hours)
    returning id into new_id;
  exception when unique_violation then
    raise exception 'There is already a request waiting for an answer';
  end;

  return new_id;
end;
$$;

-- The other person accepts or declines.
create or replace function public.respond_reply_window(p_request_id uuid, p_accept boolean)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  r public.reply_window_requests%rowtype;
  i public.interests%rowtype;
begin
  select * into r from public.reply_window_requests where id = p_request_id for update;
  if not found or r.status <> 'pending' then
    raise exception 'This request was already answered';
  end if;

  select * into i from public.interests where id = r.interest_id;
  if auth.uid() not in (i.from_user, i.to_user) or r.requested_by = auth.uid() then
    raise exception 'Only the other person can answer this';
  end if;

  if r.expires_at <= now() then
    update public.reply_window_requests set status = 'expired', decided_at = now() where id = r.id;
    raise exception 'This request has expired';
  end if;

  update public.reply_window_requests
     set status = case when p_accept then 'accepted' else 'declined' end, decided_at = now()
   where id = r.id;

  if p_accept then
    insert into public.reply_window_changes (interest_id, effective_from, hours)
    values (r.interest_id, now(), r.hours)
    on conflict (interest_id, effective_from) do update set hours = excluded.hours;
  end if;
end;
$$;

-- Requests I'm part of that still matter: ones waiting on an answer, and recent answers/expiries
-- to requests I made (so I can be told). Expired ones are marked as such here.
create or replace function public.my_reply_requests()
returns table (
  id uuid,
  interest_id uuid,
  requested_by uuid,
  hours int,
  status text,
  created_at timestamptz,
  expires_at timestamptz,
  decided_at timestamptz
)
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.reply_window_requests r
     set status = 'expired', decided_at = r.expires_at
   where r.status = 'pending' and r.expires_at <= now()
     and r.interest_id in (select x.id from public.interests x where auth.uid() in (x.from_user, x.to_user));

  return query
    select r.id, r.interest_id, r.requested_by, r.hours, r.status, r.created_at, r.expires_at, r.decided_at
      from public.reply_window_requests r
      join public.interests i on i.id = r.interest_id
     where auth.uid() in (i.from_user, i.to_user)
       and (r.status = 'pending'
            or (r.requested_by = auth.uid() and r.decided_at > now() - interval '14 days'))
     order by r.created_at;
end;
$$;

revoke all on function public.chat_window(uuid, timestamptz, text) from public, anon;
revoke all on function public.chat_reply_windows() from public, anon;
revoke all on function public.request_reply_window(uuid, int) from public, anon;
revoke all on function public.respond_reply_window(uuid, boolean) from public, anon;
revoke all on function public.my_reply_requests() from public, anon;
grant execute on function public.chat_reply_windows() to authenticated;
grant execute on function public.request_reply_window(uuid, int) to authenticated;
grant execute on function public.respond_reply_window(uuid, boolean) to authenticated;
grant execute on function public.my_reply_requests() to authenticated;
grant execute on function public.chat_window(uuid, timestamptz, text) to authenticated;

-- Ratings judge each message against the window in force when it was sent.
create or replace function public.get_ratings(p_user_ids uuid[])
returns table (user_id uuid, rating numeric, on_time int, late int)
language sql
stable
security definer
set search_path = public
as $$
  with users as (
    select distinct unnest(p_user_ids) as uid
  ),
  -- Interests someone sent to this person: answered, or still unanswered past the deadline.
  interest_events as (
    select u.uid,
           i.created_at + public.response_window(p.urgency) as due,
           coalesce(i.responded_at, i.declined_at) as responded
      from users u
      join public.interests i on i.to_user = u.uid
      left join public.positions p on p.id = i.position_id
     where i.status = 'pending'
        or coalesce(i.responded_at, i.declined_at) is not null
  ),
  -- Interests that were already overdue when their position closed. Recorded at that moment
  -- (see close_position), so reopening the position can't wipe the miss.
  missed as (
    select r.user_id as uid, r.due, null::timestamptz as responded
      from users u
      join public.missed_replies r on r.user_id = u.uid
  ),
  -- Chat messages that started a run from the other person, and this person's first reply.
  chat_events as (
    select u.uid,
           s.created_at + public.chat_window(i.id, s.created_at, p.urgency) as due,
           (select min(r.created_at)
              from public.messages r
             where r.interest_id = s.interest_id
               and r.sender_id = u.uid
               and r.created_at > s.created_at) as responded,
           i.status
      from users u
      join public.interests i on (i.from_user = u.uid or i.to_user = u.uid)
      left join public.positions p on p.id = i.position_id
      join lateral (
        select m.*, lag(m.sender_id) over (order by m.created_at) as prev_sender
          from public.messages m
         -- A deleted message from them is no longer something to answer; one of mine still
         -- counted as an answer. This matches how the app's reply timers read a chat.
         where m.interest_id = i.id
           and (m.deleted_at is null or m.sender_id = u.uid)
      ) s on true
     where s.sender_id <> u.uid
       and s.prev_sender is distinct from s.sender_id
       and s.deleted_at is null
  ),
  -- Recruiters should open the conversation: once a match is made, the first message is
  -- theirs to send, within the posting's reply window. (Matches made before response times
  -- were recorded have no start time and are skipped.)
  first_move_events as (
    select u.uid,
           i.responded_at + public.chat_window(i.id, i.responded_at, p.urgency) as due,
           (select min(m.created_at)
              from public.messages m
             where m.interest_id = i.id and m.sender_id = u.uid) as responded,
           i.status
      from users u
      join public.profiles pr on pr.id = u.uid and pr.is_recruiter
      join public.interests i on (i.from_user = u.uid or i.to_user = u.uid)
                              and i.responded_at is not null
                              and i.status in ('accepted', 'closed')
      left join public.positions p on p.id = i.position_id
     -- If the other person wrote first, within the window, their message is what's owed a
     -- reply (that's counted under chat_events), not a missed first move.
     where not exists (
       select 1 from public.messages m2
        where m2.interest_id = i.id
          and m2.sender_id <> u.uid
          and m2.deleted_at is null
          and m2.created_at <= i.responded_at + public.chat_window(i.id, i.responded_at, p.urgency)
     )
  ),
  events as (
    select uid, due, responded from interest_events
    union all
    select uid, due, responded from missed
    union all
    select uid, due, responded from chat_events
     where responded is not null or (status = 'accepted' and due < now())
    union all
    select uid, due, responded from first_move_events
     where responded is not null or (status = 'accepted' and due < now())
  ),
  ranked as (
    select uid,
           (responded is not null and responded <= due) as ok,
           row_number() over (partition by uid order by due desc) as rn
      from events
     where responded is not null or due < now()
  ),
  counts as (
    select uid,
           count(*) filter (where ok)::int as ok_count,
           count(*) filter (where not ok)::int as late_count
      from ranked
     where rn <= 30
     group by uid
  )
  select u.uid,
         round(5.0 * (coalesce(c.ok_count, 0) + 3)
               / (coalesce(c.ok_count, 0) + coalesce(c.late_count, 0) + 3), 1),
         coalesce(c.ok_count, 0),
         coalesce(c.late_count, 0)
    from users u
    left join counts c on c.uid = u.uid;
$$;


revoke all on function public.get_ratings(uuid[]) from public, anon;
grant execute on function public.get_ratings(uuid[]) to authenticated;
